# Initialize an empty dictionary to store names and phone numbers
name_phone_dict = {}

def add_name_phone(name, phone_number):
    """Add a name and phone number to the dictionary."""
    if name in name_phone_dict:
        print(f"{name} is already in the dictionary.")
    else:
        name_phone_dict[name] = phone_number
        print(f"{name}'s phone number has been added to the dictionary.")

def remove_name(name):
    """Remove a name and its corresponding phone number from the dictionary."""
    if name in name_phone_dict:
        del name_phone_dict[name]
        print(f"{name}'s phone number has been removed from the dictionary.")
    else:
        print(f"{name} is not in the dictionary.")

def search_name(name):
    """Search for a name and its corresponding phone number in the dictionary."""
    if name in name_phone_dict:
        print(f"{name}'s phone number is {name_phone_dict[name]}.")
    else:
        print(f"{name} not found in the dictionary.")

# Get user input
user_input = input("Enter a command (add, remove, search, or exit): ").lower()

while user_input != "exit":
    if user_input == "add":
        name = input("Enter a name: ")
        phone_number = input("Enter a phone number: ")
        add_name_phone(name, phone_number)

    elif user_input == "remove":
        name = input("Enter a name: ")
        remove_name(name)

    elif user_input == "search":
        name = input("Enter a name: ")
        search_name(name)

